 "content": "from collections import Counter

# Each stream instance's dense background symbol selects the corresponding bitmap.
PATTERNS = {
    1: [[0, 0, 8], [8, 8, 0], [0, 8, 0]],
    2: [[0, 0, 0], [8, 8, 8], [0, 0, 0]],
    3: [[0, 8, 8], [0, 8, 0], [0, 8, 0]],
}

def transform(grid):
    counts = Counter(v for row in grid for v in row if v != 0)
    # Frequent foreground/background color determines the 3x3 glyph.
    key = max(counts, key=counts.get)
    return [row[:] for row in PATTERNS[key]]

if __name__ == '__main__':
